     1→{% comment %}
     2→  Zip Code Checker — Theme App Extension Block
     3→  Add this block to any section in the Shopify Theme Editor.
     4→  Set the "App URL" setting to your app's base URL (e.g. https://your-app.shopify.com).
     5→{% endcomment %}
     6→
     7→<div
     8→  id="zcc-widget-{{ block.id }}"
     9→  data-shop="{{ shop.permanent_domain }}"
    10→  data-api="{{ block.settings.api_base_url | remove: '/' | append: '' }}"
    11→  data-block="{{ block.id }}"
    12→  {{ block.shopify_attributes }}
    13→></div>
    14→
    15→<script>
    16→(function () {
    17→  var ROOT_ID = "zcc-widget-{{ block.id }}";
    18→  var container = document.getElementById(ROOT_ID);
    19→  if (!container) return;
    20→
    21→  var SHOP = container.dataset.shop;
    22→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
    23→
    24→  if (!API_BASE) {
    25→    container.innerHTML =
    26→      '<p style="color:#D72C0D;font-size:14px;padding:12px;border:1px solid #D72C0D22;border-radius:6px">' +
    27→      "Zip Code Checker: Please set the App URL in the theme block settings." +
    28→      "</p>";
    29→    return;
    30→  }
    31→
    32→  // Fetch widget config, then render
    33→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
    34→    .then(function (r) { return r.json(); })
    35→    .then(function (cfg) { renderWidget(cfg); })
    36→    .catch(function () { renderWidget({}); });
    37→
    38→  function renderWidget(cfg) {
    39→    // Merge with defaults
    40→    var D = {
    41→      heading: "Check Delivery Availability",
    42→      placeholder: "Enter your zip code",
    43→      buttonText: "Check",
    44→      successMessage: "Great news! We deliver to your area.",
    45→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
    46→      notFoundMessage: "This zip code was not found in our system.",
    47→      primaryColor: "#008060",
    48→      successColor: "#008060",
    49→      errorColor: "#D72C0D",
    50→      backgroundColor: "#FFFFFF",
    51→      textColor: "#202223",
    52→      borderRadius: "8",
    53→      showEta: true,
    54→      showZone: false,
    55→      showWaitlistOnFailure: false,
    56→      customCss: "",
    57→    };
    58→    Object.keys(D).forEach(function (k) {
    59→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
    60→    });
    61→
    62→    var rad = cfg.borderRadius + "px";
    63→    var WID = "zcc-" + ROOT_ID;
    64→
    65→    // ---- Inject scoped CSS ----
    66→    var css =
    67→      "#" + WID + "{" +
    68→        "background:" + cfg.backgroundColor + ";" +
    69→        "color:" + cfg.textColor + ";" +
    70→        "border-radius:" + rad + ";" +
    71→        "padding:24px;" +
    72→        "border:1px solid #e1e3e5;" +
    73→        "max-width:480px;" +
    74→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
    75→        "box-sizing:border-box;" +
    76→      "}" +
    77→      "#" + WID + " *{box-sizing:border-box}" +
    78→      "#" + WID + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
    79→      "#" + WID + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
    80→      "#" + WID + " .zcc-input{" +
    81→        "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
    82→        "border-radius:" + rad + ";font-size:14px;outline:none;" +
    83→        "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
    84→      "}" +
    85→      "#" + WID + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
    86→      "#" + WID + " .zcc-btn{" +
    87→        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
    88→        "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
    89→        "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
    90→      "}" +
    91→      "#" + WID + " .zcc-btn:hover{opacity:.9}" +
    92→      "#" + WID + " .zcc-btn:disabled{opacity:.6;cursor:not-allowed}" +
    93→      "#" + WID + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
    94→      "#" + WID + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
    95→      "#" + WID + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
    96→      "#" + WID + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
    97→      "#" + WID + " .zcc-wl{margin-top:10px}" +
    98→      "#" + WID + " .zcc-wl-input{" +
    99→        "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
   100→        "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
   101→      "}" +
   102→      "#" + WID + " .zcc-wl-btn{" +
   103→        "background:" + cfg.errorColor + ";color:#fff;border:none;" +
   104→        "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
   105→        "cursor:pointer;width:100%;font-weight:600" +
   106→      "}" +
   107→      "#" + WID + " .zcc-wl-btn:disabled{opacity:.6;cursor:not-allowed}" +
   108→      (cfg.customCss || "");
   109→
   110→    var styleEl = document.createElement("style");
   111→    styleEl.textContent = css;
   112→    document.head.appendChild(styleEl);
   113→
   114→    // ---- Build HTML ----
   115→    container.id = WID;
   116→    container.innerHTML =
   117→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
   118→      '<div class="zcc-row">' +
   119→        '<input class="zcc-input" type="text" id="' + WID + '-inp"' +
   120→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
   121→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
   122→        '<button class="zcc-btn" id="' + WID + '-btn" type="button">' + esc(cfg.buttonText) + "</button>" +
   123→      "</div>" +
   124→      '<div id="' + WID + '-res"></div>';
   125→
   126→    var inp = document.getElementById(WID + "-inp");
   127→    var btn = document.getElementById(WID + "-btn");
   128→    var res = document.getElementById(WID + "-res");
   129→    var btnLabel = cfg.buttonText;
   130→
   131→    function checkZip() {
   132→      var zip = inp.value.trim();
   133→      if (!zip) { inp.focus(); return; }
   134→
   135→      btn.disabled = true;
   136→      btn.textContent = "\u2026";
   137→      res.innerHTML = "";
   138→
   139→      fetch(
   140→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   141→          "&zip=" + encodeURIComponent(zip)
   142→      )
   143→        .then(function (r) { return r.json(); })
   144→        .then(function (data) {
   145→          btn.disabled = false;
   146→          btn.textContent = btnLabel;
   147→
   148→          if (data.allowed) {
   149→            var html = '<div class="zcc-result ok">' + esc(data.message);
   150→            if (cfg.showEta && data.eta) {
   151→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   152→            }
   153→            if (cfg.showZone && data.zone) {
   154→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   155→            }
   156→            html += "</div>";
   157→            res.innerHTML = html;
   158→          } else {
   159→            var html = '<div class="zcc-result fail">' + esc(data.message);
   160→            if (cfg.showWaitlistOnFailure) {
   161→              html +=
   162→                '<div class="zcc-wl">' +
   163→                '<input class="zcc-wl-input" type="email" id="' + WID + '-wl-email" placeholder="Enter email to join waitlist" />' +
   164→                '<button class="zcc-wl-btn" id="' + WID + '-wl-btn" type="button">Join Waitlist</button>' +
   165→                "</div>";
   166→            }
   167→            html += "</div>";
   168→            res.innerHTML = html;
   169→
   170→            if (cfg.showWaitlistOnFailure) {
   171→              var wBtn = document.getElementById(WID + "-wl-btn");
   172→              if (wBtn) {
   173→                wBtn.addEventListener("click", function () {
   174→                  var emailEl = document.getElementById(WID + "-wl-email");
   175→                  var email = emailEl ? emailEl.value.trim() : "";
   176→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   177→                  joinWaitlist(zip, email, wBtn);
   178→                });
   179→              }
   180→            }
   181→          }
   182→        })
   183→        .catch(function () {
   184→          btn.disabled = false;
   185→          btn.textContent = btnLabel;
   186→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   187→        });
   188→    }
   189→
   190→    function joinWaitlist(zip, email, wBtn) {
   191→      wBtn.disabled = true;
   192→      wBtn.textContent = "Joining\u2026";
   193→
   194→      fetch(API_BASE + "/api/waitlist", {
   195→        method: "POST",
   196→        headers: { "Content-Type": "application/json" },
   197→        body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   198→      })
   199→        .then(function (r) { return r.json(); })
   200→        .then(function (data) {
   201→          var wlEl = wBtn.closest(".zcc-wl");
   202→          if (data.success) {
   203→            if (wlEl) wlEl.innerHTML =
   204→              '<p style="font-size:13px;margin:6px 0 0">' +
   205→              "\u2713 You\u2019ve been added to the waitlist!" +
   206→              "</p>";
   207→          } else {
   208→            wBtn.disabled = false;
   209→            wBtn.textContent = "Join Waitlist";
   210→          }
   211→        })
   212→        .catch(function () {
   213→          wBtn.disabled = false;
   214→          wBtn.textContent = "Join Waitlist";
   215→        });
   216→    }
   217→
   218→    btn.addEventListener("click", checkZip);
   219→    inp.addEventListener("keydown", function (e) {
   220→      if (e.key === "Enter") checkZip();
   221→    });
   222→  }
   223→
   224→  function esc(str) {
   225→    return String(str)
   226→      .replace(/&/g, "&amp;")
   227→      .replace(/</g, "&lt;")
   228→      .replace(/>/g, "&gt;")
   229→      .replace(/"/g, "&quot;");
   230→  }
   231→
   232→  function escAttr(str) {
   233→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
   234→  }
   235→})();
   236→</script>
   237→
   238→{% schema %}
   239→{
   240→  "name": "Zip Code Checker",
   241→  "target": "section",
   242→  "settings": [
   243→    {
   244→      "type": "text",
   245→      "id": "api_base_url",
   246→      "label": "App URL",
   247→      "info": "Paste your Zip Code Checker app URL here (e.g. https://your-app.shopify.com). Find this in the Widget Customization page of the app."
   248→    }
   249→  ],
   250→  "presets": [
   251→    {
   252→      "name": "Zip Code Checker"
   253→    }
   254→  ]
   255→}
   256→{% endschema %}
